(42861, 'Psalms 38:2', 'Psalms', 38, 2, 'په خپلو غشو دې زخمي کړمه زه او په خپل لاس باندې دې ووهلم', 'په خپلو غشو دې زخمی کرمه زه او په خپل لاس باندې دې ووهلم', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42862, 'Psalms 38:3', 'Psalms', 38, 3, 'زما بدن کې روغ ځای نشته ستا د قهر له لاسه حتی هډوکي مې خوږیږي د ګناه له لاسه', 'زما بدن کې روغ جای نشته ستا د قهر له لاسه حتی هدوکی مې خوزیزی د ګناه له لاسه', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42863, 'Psalms 38:4', 'Psalms', 38, 4, 'زه د خپلو ګناهونو په دریاب کې یم ډوب شوی هغه دي دومره درانه چې وړلی یې نه شم', 'زه د خپلو ګناهونو په دریاب کې یم دوب شوی هغه دی دومره درانه چې ورلی یې نه شم', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42864, 'Psalms 38:5', 'Psalms', 38, 5, 'په سبب زما د خپلې بې‌عقلۍ پرهارونه مې خوسا شول بوی ترې خېژي', 'په سبب زما د خپلې بې‌عقلی پرهارونه مې خوسا شول بوی ترې خېژی', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
