(42866, 'Psalms 38:7', 'Psalms', 38, 7, 'زه له تبې نه خوټېږم زما بدن کې روغ ځای نشته', 'زه له تبې نه خوتېزم زما بدن کې روغ جای نشته', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42867, 'Psalms 38:8', 'Psalms', 38, 8, 'زه له کاره یم لوېدلی او بیخي یمه مات شوی زما زړه دی ناقراره او له درده زګېروي کړمه', 'زه له کاره یم لوېدلی او بیخی یمه مات شوی زما زره دی ناقراره او له درده زګېروی کرمه', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42868, 'Psalms 38:9', 'Psalms', 38, 9, 'ای څښتنه، ته پوهېږې چې زه څه ارمان لرمه ټول زګېروي ته زما اورې', 'ای چشتنه، ته پوهېزې چې زه چه ارمان لرمه تول زګېروی ته زما اورې', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42869, 'Psalms 38:10', 'Psalms', 38, 10, 'زړه مې درزیږي او قوت رانه لاړ زما د سترګو دید کمزوری شولو', 'زره مې درزیزی او قوت رانه لار زما د سترګو دید کمزوری شولو', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42870, 'Psalms 38:11', 'Psalms', 38, 11, 'نه رانژدې کیږي په سبب د ناروغۍ راته ټول زما ملګري او دوستان زما حتی تر دې چې خپل خپلوان هم رانه لېرې ګرځي', 'نه رانژدې کیزی په سبب د ناروغی راته تول زما ملګری او دوستان زما حتی تر دې چې خپل خپلوان هم رانه لېرې ګرجی', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42871, 'Psalms 38:12', 'Psalms', 38, 12, 'هغوی چې غواړي چې ما مړ کړي راته ږدي دامونه هغوی چې غواړي راته ورسوي زیان د بربادۍ کوي ګواښونه راته ټوله ورځ دوی دسیسې جوړوي او دروغ وایي', 'هغوی چې غواری چې ما مر کری راته زدی دامونه هغوی چې غواری راته ورسوی زیان د بربادی کوی ګواشونه راته توله ورج دوی دسیسې جوروی او دروغ وایی', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42872, 'Psalms 38:13', 'Psalms', 38, 13, 'خو زه د هغه کوڼ په شان یم چې څه نه اورمه او د هغه ګونګ په شان یم چې هېڅ نه کوي خبرې', 'خو زه د هغه کون په شان یم چې چه نه اورمه او د هغه ګونګ په شان یم چې هېچ نه کوی خبرې', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42873, 'Psalms 38:14', 'Psalms', 38, 14, 'زه یم د هغه چا په څېر چې خپله دفاع کې نه شي دلیل ویلی ځکه چې نه اوري', 'زه یم د هغه چا په چېر چې خپله دفاع کې نه شی دلیل ویلی جکه چې نه اوری', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42874, 'Psalms 38:15', 'Psalms', 38, 15, 'خو تا باندې باور لرم څښتنه او ای زما څښتنه خدایه، راکوې به ته ځواب', 'خو تا باندې باور لرم چشتنه او ای زما چشتنه خدایه، راکوې به ته جواب', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42875, 'Psalms 38:16', 'Psalms', 38, 16, 'سوال مې وکړ: «مه پرېږده دښمن زما چې وکړي خوشحالي زما په غم باندې مه پرېږده هغوی چې لافې ووهي زما په ناکامۍ او بدبختۍ باندې»', 'سوال مې وکر: «مه پرېزده دشمن زما چې وکری خوشحالی زما په غم باندې مه پرېزده هغوی چې لافې ووهی زما په ناکامی او بدبختی باندې»', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(42876, 'Psalms 38:17', 'Psalms', 38, 17, 'یمه نژدې چې زه راپرېوځمه مدام دي مل راسره زما دردونه', 'یمه نژدې چې زه راپرېوجمه مدام دی مل راسره زما دردونه', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
